jsonTools.init:
function init(eli) {
  var STORE = window.STORE_CONFIG || "config";
  var KEY_PREFIX = "_rn_narr_";   // bounded buffer per CLAUDE.md
  var MAX_CACHED = 5;
  // Bump this any time the AI's output shape changes — it's baked into
  // the cache key so old cached results never get reused under the new
  // schema. v2: bullets are objects {text, sections[]}. v3: bullets also
  // carry evidence[] (anti-hallucination citations); themes can include
  // "Other" catch-all; coverage is now required (no silent drops).
  var SCHEMA_VERSION = 12;

  // ── Cache (per docHash) ────────────────────────────────────────────
  function _save(docHash, payload) {
    var row = { key: KEY_PREFIX + docHash, payload: payload, savedAt: Date.now() };
    try {
      return eli.storage.put(STORE, row).then(function () { _prune(); }).catch(function () {});
    } catch (_e) { return Promise.resolve(); }
  }
  function _load(docHash) {
    try {
      return eli.storage.get(STORE, KEY_PREFIX + docHash)
        .then(function (r) { return r ? r.payload : null; })
        .catch(function () { return null; });
    } catch (_e) { return Promise.resolve(null); }
  }
  function _prune() {
    try {
      return eli.storage.getAll(STORE).then(function (all) {
        if (!Array.isArray(all)) return;
        var mine = all.filter(function (r) {
          return r && typeof r.key === "string" && r.key.indexOf(KEY_PREFIX) === 0;
        });
        mine.sort(function (a, b) { return (b.savedAt || 0) - (a.savedAt || 0); });
        var excess = mine.slice(MAX_CACHED);
        return Promise.all(excess.map(function (r) {
          return eli.storage.delete(STORE, r.key).catch(function () {});
        }));
      }).catch(function () {});
    } catch (_e) { return Promise.resolve(); }
  }

  // ── Cheap djb2 hash for cache keys ────────────────────────────────
  function _hash(s) {
    var h = 5381, str = String(s || "");
    for (var i = 0; i < str.length; i++) h = ((h << 5) + h + str.charCodeAt(i)) | 0;
    return (h >>> 0).toString(36);
  }

  // ── Get current user's name (to distinguish self vs counterparty) ──
  function _currentUserName() {
    try {
      var ident = (eli.tools && eli.tools.userIdentity) ? eli.tools.userIdentity() : null;
      if (ident) {
        return String(ident.name || ident.fullName || ident.firstName || "").trim() || null;
      }
    } catch (_e) {}
    try {
      var n = (eli.compat && eli.compat.lsGet) ? eli.compat.lsGet("eli_user_name") : null;
      if (n) return String(n).trim();
    } catch (_e) {}
    return null;
  }

  // Pre-extract section references from a string. Matches "Section X.Y",
  // "Sec. X.Y", "§ X.Y", "Article III", "Art. 7". Returns deduplicated
  // section numbers (the bit AFTER the keyword), preserving order. This
  // is FAR more reliable than asking the AI to spot section refs inside
  // a 100-char window — the JS regex never misses what's there.
  function _extractSectionHints(text) {
    if (!text) return [];
    var hints = [];
    var re = /\b(?:Section|Sec\.?|§|Article|Art\.?)\s+([0-9IVXLCDM][\w.\-]*)/gi;
    var m;
    while ((m = re.exec(text)) !== null) {
      if (m[1]) hints.push(m[1]);
    }
    // Dedup while preserving first-occurrence order.
    var seen = {}, out = [];
    hints.forEach(function (h) { if (!seen[h]) { seen[h] = true; out.push(h); } });
    return out;
  }

  // ── Atomic-edit splitter ─────────────────────────────────────────
  // Break a single TrackedChange's text into separate semantic edits
  // so the AI can't compress them into one bullet. Splits on:
  //   1. Sentence boundaries (period + space + capital, !, ?)
  //   2. Paragraph breaks
  //   3. Numbered/lettered list separators ("(a) ... (b) ...")
  // Trims each piece. Filters out fragments < 15 chars (likely partial
  // splits from abbreviations). Preserves the input text unchanged if
  // the result would be just one piece.
  function _splitAtomicEdits(text) {
    var raw = String(text || "").trim();
    if (!raw) return [];
    // Pre-protect common abbreviations from sentence-split: Mr./Inc./
    // No./Sec./Art./etc./i.e./e.g./U.S./vs.
    var ABBR_TOKEN = "";
    var protect = raw
      .replace(/\b(Mr|Mrs|Ms|Dr|Inc|Corp|Co|Ltd|LLC|LP|No|Sec|Art|Para|Ch|Vol|Ed|Vs|cf|al|etc|i\.e|e\.g|U\.S|U\.K)\./gi,
        function (m) { return m.replace(/\./g, ABBR_TOKEN); });
    // Split on:
    //   • sentence end: . / ! / ? followed by whitespace + capital letter or "("
    //   • paragraph break
    //   • lettered list separator: ;(a) or ; (a) or .(a) starting next clause
    var pieces = protect.split(/(?<=[.!?])\s+(?=[A-Z(])|[\r\n]+|(?<=;)\s+(?=\([a-z]\))/g);
    pieces = pieces.map(function (p) {
      return p.replace(new RegExp(ABBR_TOKEN, "g"), ".").trim();
    }).filter(function (p) {
      // Drop fragments too short to be a meaningful edit (likely artifacts).
      return p.length >= 15;
    });
    // If the split produced nothing useful, return the original whole.
    if (pieces.length <= 1) return [raw];
    return pieces;
  }

  // ── Read tracked changes + author + surrounding context ─────────────
  // Pulls each TrackedChange's text, author, type, a 200-char context
  // window from body.text, AND pre-extracts section refs from that
  // context so the AI doesn't have to spot them itself. Filters out
  // "formatting" type (non-substantive by definition).
  function _readChanges() {
    return eli.host.runRaw("redline_narrator:read", function (ctx) {
      var body = ctx.document.body;
      body.load("text");
      var tcs = body.getTrackedChanges();
      tcs.load("items");
      return ctx.sync().then(function () {
        var items = tcs.items || [];
        items.forEach(function (tc) { tc.load("text,author,type,date"); });
        return ctx.sync().then(function () {
          var bodyText = body.text || "";
          var changes = items.map(function (tc) {
            var t = String(tc.text || "").trim();
            var contextStr = "";
            if (t) {
              var pos = bodyText.indexOf(t);
              if (pos !== -1) {
                // Paragraph-boundary context — walk backwards/forwards to
                // the nearest paragraph break (\r or \n) instead of an
                // arbitrary char count. This gives the AI the FULL
                // paragraph(s) the change sits in — no truncation of
                // multi-clause IP/indemnity restructurings, no clipped
                // license-back definitions. We also extend by ONE more
                // paragraph on each side so the AI sees the immediate
                // context (defined terms, lead-in clauses).
                var s = pos;
                var e = pos + t.length;
                // Walk back two paragraph breaks
                for (var bk = 0; bk < 2 && s > 0; bk++) {
                  var prev = bodyText.lastIndexOf("\r", s - 1);
                  var prev2 = bodyText.lastIndexOf("\n", s - 1);
                  var stop = Math.max(prev, prev2);
                  if (stop < 0) { s = 0; break; }
                  s = stop;
                }
                // Walk forward two paragraph breaks
                for (var fk = 0; fk < 2 && e < bodyText.length; fk++) {
                  var nxt = bodyText.indexOf("\r", e + 1);
                  var nxt2 = bodyText.indexOf("\n", e + 1);
                  var pick = (nxt < 0) ? nxt2 : (nxt2 < 0 ? nxt : Math.min(nxt, nxt2));
                  if (pick < 0) { e = bodyText.length; break; }
                  e = pick;
                }
                contextStr = bodyText.substring(s, e).replace(/[\r\n]+/g, " ¶ ").replace(/\s+/g, " ").trim();
              }
            }
            var hints = _extractSectionHints(t + " " + contextStr);
            return {
              type: String(tc.type || "unknown").toLowerCase(),
              author: String(tc.author || "").trim() || "Unknown",
              text: t,
              context: contextStr,
              sectionHints: hints,
            };
          }).filter(function (c) {
            // Drop empty-text changes AND formatting-only changes.
            return c.text.length > 0 && c.type !== "formatting";
          });

          // ─ Atomic split ──────────────────────────────────────────────
          // Word groups consecutive edits into one TrackedChange. A single
          // tc.text can contain 4 new definitions + a license grant + an
          // ownership rule. Models compress that into one bullet ~always.
          // So before the AI sees it, split each multi-sentence change
          // into atomic sub-changes (one sentence each, with the original
          // change # preserved as parentChangeIdx for traceability).
          var atomized = [];
          changes.forEach(function (c, idx) {
            var subs = _splitAtomicEdits(c.text);
            if (subs.length <= 1) {
              atomized.push(Object.assign({}, c, { parentChangeIdx: idx + 1, partIdx: 1, partCount: 1 }));
              return;
            }
            subs.forEach(function (s, si) {
              atomized.push(Object.assign({}, c, {
                text: s,
                parentChangeIdx: idx + 1,
                partIdx: si + 1,
                partCount: subs.length,
                // each sub-change inherits the same section hints — they're
                // about the SAME spot in the doc, just different semantic edits
                sectionHints: c.sectionHints || [],
              }));
            });
          });

          return { bodyText: bodyText, changes: atomized };
        });
      });
    });
  }

  // ── Build AI prompt ───────────────────────────────────────────────
  function _buildPrompt(changes, selfName) {
    // Authors block — distinct names with their change counts. Helps the
    // AI see who's making most of the edits at a glance.
    var byAuthor = {};
    changes.forEach(function (c) { byAuthor[c.author] = (byAuthor[c.author] || 0) + 1; });
    var authorsBlock = Object.keys(byAuthor).map(function (a) {
      var marker = (selfName && a.toLowerCase() === selfName.toLowerCase()) ? " ← YOU" : "";
      return "  • " + a + " (" + byAuthor[a] + " change" + (byAuthor[a] === 1 ? "" : "s") + ")" + marker;
    }).join("\n");

    // Per-change block — author + type + text + context + JS-extracted
    // section hints. The hints field is what makes the locate pills
    // reliable: if a section number appears anywhere in the text/context,
    // it's already in c.sectionHints — the AI doesn't have to spot it,
    // just decide which hint(s) apply to which bullet.
    var changesBlock = changes.map(function (c, i) {
      var tag = c.type === "deletion" ? "DELETED (original text)"
              : c.type === "insertion" ? "INSERTED (new text)"
              : c.type === "moved" ? "MOVED" : c.type.toUpperCase();
      var attribution = (selfName && c.author.toLowerCase() === selfName.toLowerCase())
        ? "You" : c.author;
      // Atomic-split tag: when one Word edit was broken into pieces by the
      // pre-processor, show "Word Edit #N, part X/Y" so the AI knows these
      // rows are semantically distinct edits the user typed together.
      var parentTag = "";
      if (c.partCount > 1) {
        parentTag = " (part " + c.partIdx + " of " + c.partCount +
          " from Word edit #" + c.parentChangeIdx + ")";
      }
      var line = "Edit #" + (i + 1) + parentTag + " — by " + attribution + " — " + tag + ":";
      line += "\n  Text: \"" + c.text + "\"";
      if (c.context) line += "\n  Surrounding context: \"…" + c.context + "…\"";
      if (c.sectionHints && c.sectionHints.length) {
        line += "\n  Section hints (already parsed for you): [" +
          c.sectionHints.map(function (h) { return "\"" + h + "\""; }).join(", ") + "]";
      } else {
        line += "\n  Section hints: [] (no section reference found in context)";
      }
      return line;
    }).join("\n\n");

    // Publication mention check — pre-screen the input. If the word
    // "publication" / "publish" / "manuscript" appears anywhere in the
    // changes, surface a STRICT directive that the AI must address it.
    var pubRegex = /\b(publication|publish(?:ing|es|ed)?|manuscript|abstract\b|published?\s+results)\b/i;
    var hasPublicationContent = changes.some(function (c) {
      return pubRegex.test(c.text) || pubRegex.test(c.context || "");
    });

    return [
      "You are writing a plain-English changelog of tracked changes in a legal contract.",
      "Audience: a busy lawyer who wants the gist in 15 seconds.",
      "",
      "═══ AUTHORS ═══",
      (selfName ? "YOU are: " + selfName : "Current user name not detected — treat all authors as potential counterparty."),
      "",
      "Authors who made changes:",
      authorsBlock,
      "",
      "═══ FOCUS RULE — STRICT ═══",
      "ONLY summarize changes made by people OTHER THAN you (the counterparty's edits).",
      "If a change is marked \"by You\", IGNORE IT — do not mention it anywhere in the",
      "summary, not even in passing. We want to see what the OTHER SIDE did to OUR draft.",
      (selfName
        ? "If only one non-'You' author exists, refer to them as \"the counterparty\" in"
          + "\nthe headline. If multiple non-'You' authors, name them or say \"counterparty\"."
        : "Pick the author who made the most changes as the counterparty if you must guess.")
        + "",
      "",
      (hasPublicationContent
        ? "═══ PUBLICATION CHECK — CRITICAL ═══\n" +
          "Publication-related content (publication rights, publishing, manuscripts, abstracts,\n" +
          "publication of results) APPEARS in the counterparty's changes. You MUST address\n" +
          "publication explicitly in the summary. Add a dedicated theme called \"Publication\"\n" +
          "(icon 📄 or 📰) with at least one bullet that names what the counterparty did to\n" +
          "the publication terms. Do NOT bury publication under a generic theme like \"IP\" or\n" +
          "\"Process\" — give it its own theme. If multiple publication bullets exist, group\n" +
          "them together in that theme.\n"
        : "═══ PUBLICATION CHECK ═══\n" +
          "No publication-related content was detected in the counterparty's changes. Do not\n" +
          "fabricate a publication theme — skip it.\n"),
      "",
      "═══ INPUT — every tracked change ═══",
      "Type values:",
      "  • INSERTED — counterparty ADDED this text to our draft",
      "  • DELETED — counterparty REMOVED this text from our draft (this IS the original wording)",
      "  • MOVED — counterparty relocated this text",
      "",
      "**CRITICAL DISTINCTION — Text vs Surrounding context:**",
      "Each Edit has TWO fields:",
      "  • Text: the EXACT counterparty change. This is what was inserted/deleted.",
      "  • Surrounding context: text around the change for orientation. THIS INCLUDES",
      "    PRE-EXISTING CONTRACT LANGUAGE that the counterparty did NOT change.",
      "",
      "**YOU MAY ONLY CITE TEXT FROM THE `Text` FIELD AS EVIDENCE.** Never cite text",
      "from `Surrounding context` as if it were a counterparty insertion. Doing so",
      "fabricates a change that didn't happen. The post-validator will drop any",
      "bullet whose evidence quote can't be found in any Edit's Text field, so",
      "context-derived quotes won't survive — but it's much better to not write",
      "them in the first place.",
      "",
      "Example: if Text = 'University shall own all inventions...' and the context",
      "around it includes 'Colgate shall exclusively own all Research Project IP'",
      "(which was already there), do NOT write a bullet claiming Colgate added the",
      "exclusive-ownership language. That sentence was pre-existing. Your bullet",
      "must describe the ACTUAL inserted text in Text.",
      "",
      "**SIBLING NOTE:** Some Edits are tagged \"(part X of Y from Word edit #N)\".",
      "Those Edits are SEQUENTIAL CLAUSES of one block of text the counterparty",
      "typed/pasted as a single unit. Read them as a coherent block — a later clause",
      "may qualify, override, or contradict an earlier one. (See SIBLING SYNTHESIS",
      "& CONTRADICTION CHECK rule below.)",
      "",
      "TOTAL CHANGES: " + changes.length,
      "",
      changesBlock,
      "",
      "═══ OUTPUT — JSON matching the schema ═══",
      "  • headline: ONE sentence, MAX 18 words, active voice, concrete verbs.",
      "    Frame it as \"Counterparty did X, Y, Z.\" or \"[Name] narrowed X and added Y.\"",
      "  • themes: 4–7 thematic groupings (more themes = better coverage). For each:",
      "      - icon: a single emoji that fits the theme (🛡 risk, 💰 money, 🔒 IP,",
      "        ⏱ time, 📋 process, 🤝 relationship, 📦 deliverables, 📄 publication,",
      "        📌 for the catch-all \"Other / Notable\" theme).",
      "      - title: 2–3 word theme name. The catch-all is titled \"Other (Substantive)\".",
      "      - bullets: array of OBJECTS, each with:",
      "         - text: 1 sentence describing the change in plain English.",
      "         - sections: ARRAY of section refs (strings) where this change lives.",
      "           **STRONGLY PREFER the pre-parsed `Section hints` field on each input",
      "           change** — those are extracted by regex, so they're reliable. If a",
      "           bullet describes change #5, copy change #5's Section hints into the",
      "           bullet's sections array. If a bullet covers multiple changes, union",
      "           their hints. Empty [] only when EVERY source change has empty hints.",
      "           Format: bare numbers/identifiers — \"7.1\" or \"III\" — no prefix.",
      "         - evidence: ARRAY of citations grounding the bullet in the input.",
      "           **EVERY bullet MUST have AT LEAST ONE and AT MOST ONE evidence entry,",
      "           with ONE narrow exception (below). Bullets with empty evidence ARE",
      "           NOT ALLOWED — drop them entirely.** Each entry:",
      "             • action: one of \"deleted\" | \"inserted\" | \"replaced\" | \"moved\"",
      "             • quote: VERBATIM text drawn DIRECTLY from a counterparty change's",
      "               text or context. NO TRUNCATION — include the FULL relevant clause,",
      "               sentence, or definition. No paraphrase, no edits, no \"…\" ellipses.",
      "               If a definition runs 3 lines, quote all 3 lines. The reader needs",
      "               enough text to scan the doc for and trust the bullet's claim.",
      "             • replacement: ONLY for \"replaced\" actions — the new text the",
      "               counterparty substituted in (verbatim). Omit for other actions.",
      "",
      "           **MULTI-EVIDENCE EXCEPTION (narrow):** A single bullet may have TWO",
      "           evidence entries ONLY when it describes a true substitution — a",
      "           paired DELETE + INSERT at the SAME location (e.g., a phrase swap",
      "           on one line). Use one DELETE evidence + one INSERT evidence, or one",
      "           REPLACED entry with both quote and replacement.",
      "",
      "           **DO NOT use multi-evidence to merge sibling clauses from one Word",
      "           edit.** Even when 4 sentences were typed together (\"part 1 of 4 from",
      "           Word edit #N\" etc.), each gets its OWN BULLET with ONE evidence entry",
      "           quoting only its own sentence. Sibling clauses are NOT a substitution",
      "           and the multi-evidence exception does not apply to them.",
      "",
      "═══ COVERAGE RULE — STRICT ═══",
      "Every SUBSTANTIVE counterparty Edit # in the input must be referenced by at",
      "least one bullet across all themes. NO substantive Edit may be silently",
      "dropped. The input has been pre-atomized — each Edit # IS already a single",
      "semantic edit, so the mapping is essentially Edit # → bullet. If Edits #4,",
      "#5, #6 came from the same Word edit (you'll see \"part X of Y from Word edit\"),",
      "you STILL emit one bullet per Edit # — each is a separately verifiable claim.",
      "",
      "Before you finish, do a coverage check: read through every Edit # and confirm",
      "you have at least one bullet whose evidence quotes that Edit's text. If any",
      "substantive Edit is uncovered, add a bullet for it under Other (Substantive).",
      "",
      "If a substantive change doesn't fit a primary theme (Risk, Money,",
      "Time, IP, etc.), put it under the \"Other (Substantive)\" theme. Use that",
      "theme to catch:",
      "  • Reservations of rights / disclaimers added or removed",
      "  • Notice / cure provisions",
      "  • Assignment / change-of-control language",
      "  • Force majeure additions or carve-outs",
      "  • Survival clauses for non-obvious sections",
      "  • Audit rights, books-and-records language",
      "  • New defined terms / definitions introduced or removed",
      "  • License grants / license-backs added or removed",
      "  • Any other counterparty edit that's substantive but doesn't fit cleanly",
      "Only the \"Other\" theme can have a generic title. All primary themes should",
      "be specific (e.g., \"Indemnity\" not \"Legal\", \"Payment\" not \"Money\").",
      "",
      "═══ ANTI-AGGREGATION RULE — DO NOT COMPRESS ═══",
      "**CRITICAL:** A single \"Change #N\" in the input may contain MANY distinct",
      "semantic edits, because Word tracks a pasted block as ONE TrackedChange even",
      "though it added 4 new definitions + a new license + a new ownership rule.",
      "You MUST scan EACH change's text for multiple semantic edits and split them",
      "into SEPARATE bullets. Look for:",
      "  • Multiple sentences in one insertion — each sentence is likely its own edit",
      "  • Multiple defined terms introduced inside one Change (quotes around capitalized",
      "    nouns like \"University Inventions\" = a new defined term = its own bullet)",
      "  • \"Each Party shall…\" patterns (often hide reciprocal obligations — split by party)",
      "  • Sweeping verbs that touch multiple topics in one sentence (own + license + assign)",
      "",
      "When several distinct substantive edits appear together in one paragraph or",
      "redline block, you MUST emit SEPARATE bullets for each — do NOT collapse them",
      "into a single \"the counterparty restructured X\" summary. A reader needs to",
      "know each discrete edit landed. Treat each of the following as its own bullet:",
      "  • Each new definition introduced (\"University Inventions\", \"Joint Inventions\")",
      "  • Each new ownership / allocation rule",
      "  • Each license grant or license-back",
      "  • Each new carve-out, exception, or proviso",
      "  • Each new representation, warranty, or covenant",
      "  • Each scope expansion or narrowing",
      "",
      "WORKED EXAMPLE — what NOT to do, then what to do:",
      "Input: one tracked-changes paragraph in §10 where the counterparty deleted",
      "  \"Each Party\" and inserted a four-clause IP regime: definitions for",
      "  University Inventions, Colgate Inventions, Joint Inventions; a sweeping",
      "  \"Colgate shall exclusively own all Research Project IP\"; and a license-",
      "  back to University for non-commercial research use.",
      "",
      "WRONG (one bullet, hides four edits behind a summary):",
      "  ✗ \"Counterparty revised IP ownership to grant Colgate exclusive rights",
      "     to Research Project IP.\"",
      "",
      "RIGHT (one bullet per discrete edit, each with evidence):",
      "  ✓ \"Introduced 'University Inventions' as a defined term covering inventions",
      "     conceived solely by University staff.\" — [INSERTED] \"University shall own all inventions first conceived...\"",
      "  ✓ \"Introduced 'Colgate Inventions' as a defined term covering inventions",
      "     conceived solely by Colgate staff.\" — [INSERTED] \"Colgate shall own all inventions otherwise first conceived...\"",
      "  ✓ \"Introduced 'Joint Inventions' as a defined term covering jointly",
      "     conceived inventions.\" — [INSERTED] \"The Parties shall jointly own all inventions...\"",
      "  ✓ \"Granted Colgate exclusive ownership of all Research Project IP — sits",
      "     on top of the new invention categories.\" — [INSERTED] \"Colgate shall exclusively own all right, title and interest...\"",
      "  ✓ \"Narrowed the cross-license grant from 'Each Party' to 'University' —",
      "     license-back now runs one direction only.\" — [REPLACED] \"Each Party\" → \"University\"",
      "  ✓ \"Added a non-commercial-research license-back to University covering all",
      "     Deliverables.\" — [INSERTED] \"non-exclusive, royalty-free, perpetual, irrevocable, worldwide license...\"",
      "",
      "If you find yourself writing one bullet for a multi-sentence insertion, STOP",
      "and split it. One bullet per distinct semantic edit.",
      "",
      "═══ SIBLING SYNTHESIS & CONTRADICTION CHECK — STRICT ═══",
      "After atomic-splitting (which keeps each edit separate for receipts), you MUST",
      "read sibling Edits — those marked \"(part X of Y from Word edit #N)\" — TOGETHER",
      "before writing their bullets. They were typed/pasted as ONE block by the",
      "counterparty, meaning they are intended to read as a coherent unit.",
      "",
      "**REQUIRED:** When sibling Edits are mutually inconsistent — when a later",
      "clause sweepingly overrides, contradicts, or qualifies an earlier one — the",
      "bullets MUST surface that tension, not paper over it. A lawyer will catch the",
      "contradiction; the summary that doesn't flag it is misleading.",
      "",
      "EXAMPLE — what NOT to do:",
      "Sibling Edits in one Word edit:",
      "  [1] \"University shall own all inventions conceived by University employees.\"",
      "  [2] \"Colgate shall own all inventions conceived by Colgate employees.\"",
      "  [3] \"The Parties shall jointly own inventions conceived by both.\"",
      "  [4] \"Colgate shall exclusively own all right, title and interest in and to",
      "       all Research Project IP.\"",
      "",
      "WRONG (each bullet states its sentence in isolation; sentence 4 nullifies 1-3,",
      "but the bullet doesn't say so):",
      "  ✗ \"Introduced 'University Inventions' as a defined term.\"",
      "  ✗ \"Granted Colgate exclusive ownership of all Research Project IP.\"  ← misleading",
      "    [reader thinks both bullets are independently true; in reality, bullet 2 may",
      "     swallow bullet 1]",
      "",
      "RIGHT (the conflicting bullet acknowledges the tension):",
      "  ✓ \"Introduced 'University Inventions' as a defined term covering inventions",
      "     conceived solely by University staff — see tension flag below.\"",
      "  ✓ \"Introduced 'Colgate Inventions' as a defined term — see tension flag.\"",
      "  ✓ \"Introduced 'Joint Inventions' as a defined term — see tension flag.\"",
      "  ✓ \"⚠ Then sweepingly grants Colgate exclusive ownership of ALL Research",
      "     Project IP — APPEARS TO OVERRIDE the per-party allocations in the prior",
      "     three bullets. Tension worth flagging: is Research Project IP narrower than",
      "     'inventions,' or is Colgate quietly nullifying the carve-outs?\"",
      "",
      "When in doubt: USE A ⚠ PREFIX on the bullet text to mark a tension/contradiction",
      "the reader should investigate. Don't soft-pedal contradictions — a flagged",
      "tension is more useful than a smooth summary that misleads.",
      "",
      "═══ STRICT RULES ═══",
      "  • SKIP non-substantive changes entirely. Non-substantive means:",
      "    typos, capitalization, punctuation, formatting, whitespace, re-ordering,",
      "    definitional reshuffles, AND the following housekeeping classes:",
      "      ◦ Party address corrections / mailing address updates / suite numbers",
      "      ◦ Contact info updates: phone, fax, email, attention-line names",
      "      ◦ Party name spelling fixes (\"University of Illinois Chicago\" →",
      "        \"University of Illinois at Chicago\") and legal-entity formatting",
      "      ◦ Date format normalization (\"3/15/26\" → \"March 15, 2026\")",
      "      ◦ Signature-block updates / title corrections / entity-type abbreviations",
      "    **EXCEPTION — these ARE substantive when they appear inside a Notice",
      "    provision** (\"All notices shall be delivered to…\"), because they change",
      "    where legal notices get sent. If a change is in or adjacent to a Notice",
      "    section, treat it as substantive (Other (Substantive) theme, label it",
      "    \"Notice address updated — verify your processes route here\"). Otherwise,",
      "    skip it.",
      "  • A paralegal-auto-accept test: if a junior could safely accept the change",
      "    without partner review, it's housekeeping — skip. If a partner would want",
      "    to weigh in, it's substantive — include.",
      "  • Active voice. Concrete verbs: \"narrowed\", \"added\", \"shifted\",",
      "    \"deleted\", \"expanded\", \"capped\", \"removed\", \"introduced\",",
      "    \"replaced\", \"swapped\".",
      "  • No legalese. Talk like a partner briefing an associate.",
      "  • If a change's meaning isn't clear from context, do NOT invent one.",
      "    Either describe it generically with the quoted text as the evidence,",
      "    OR skip it (only if non-substantive).",
      "  • If ALL counterparty changes are non-substantive, return an empty themes",
      "    array and headline: \"Counterparty made only stylistic changes — no substantive edits.\"",
      "  • If NO non-You authors exist at all, headline: \"Only your edits found — nothing from the counterparty to summarize.\"",
      "",
      "═══ FINAL SELF-CHECK BEFORE RETURNING ═══",
      "Walk through this checklist on your draft output before emitting JSON:",
      "  1. **1:1 mapping.** Count substantive counterparty Edit #s in the input.",
      "     Count bullets in your output. The numbers should be approximately equal.",
      "     If you have 8 substantive Edits but only 4 bullets, you compressed — go",
      "     back and split.",
      "  2. **No bullet covers more than one Edit.** Open each bullet's evidence.",
      "     If it has more than one entry AND the entries are NOT a paired delete+",
      "     insert at one location, SPLIT that bullet into one per evidence entry.",
      "  3. **Every Edit has a bullet.** Cross-reference: for each Edit # in the",
      "     input, find the bullet that quotes its text. If any Edit is uncovered,",
      "     add a bullet for it (use Other (Substantive) if no theme fits).",
      "  4. **Tension flagged, not merged.** If you found two bullets that contradict",
      "     each other (typically siblings from one Word edit), DO NOT merge them.",
      "     Keep them separate, and prepend ⚠ to the bullet text on each one with a",
      "     short tension note (e.g., \"⚠ Conflicts with bullet about X — clarify.\").",
      "",
      "Return ONLY the JSON.",
    ].join("\n");
  }

  // ── AI call ───────────────────────────────────────────────────────
  function _generate(changes, selfName) {
    var schema = {
      type: "object",
      properties: {
        headline: { type: "string" },
        themes: {
          type: "array",
          items: {
            type: "object",
            properties: {
              icon: { type: "string" },
              title: { type: "string" },
              bullets: {
                type: "array",
                items: {
                  type: "object",
                  properties: {
                    text: { type: "string" },
                    sections: { type: "array", items: { type: "string" } },
                    // Evidence — what changed, in the COUNTERPARTY'S OWN WORDS.
                    // The AI must quote verbatim from the input change text
                    // and label the action (deleted / inserted / replaced).
                    // Empty evidence array = bullet must be dropped — we
                    // refuse to render claims we can't trace.
                    evidence: {
                      type: "array",
                      items: {
                        type: "object",
                        properties: {
                          action: { type: "string", description: "deleted | inserted | replaced | moved" },
                          quote: { type: "string", description: "Verbatim text from a change, ≤ 60 chars" },
                          replacement: { type: "string", description: "For 'replaced' actions, the new text" },
                        },
                        required: ["action", "quote"],
                      },
                    },
                  },
                  required: ["text", "evidence"],
                },
              },
            },
          },
        },
      },
      required: ["headline", "themes"],
    };
    var prompt = _buildPrompt(changes, selfName);
    return eli.ai.completeJSON(prompt, schema, { sanitize: false })
      .then(function (rawResult) {
        // Normalize first — AI sometimes returns evidence as a single
        // object instead of array. Wrap into array so downstream code
        // can assume arrays everywhere.
        var normalized = _normalizeEvidence(JSON.parse(JSON.stringify(rawResult || {})));
        // Validate evidence quotes against known atomic-edit text. If a
        // quote doesn't appear in ANY known edit, the AI hallucinated it
        // from the context window — DROP the bullet.
        var validated = _validateEvidence(normalized, changes);
        // Then enforce 1:1 (split multi-evidence non-substitutions).
        var enforced = _enforceOneToOne(validated);
        if (enforced && typeof enforced === "object") {
          enforced._debug = {
            inputChanges: changes,
            rawAiOutput: rawResult,
            droppedBullets: validated._droppedBullets || [],
            promptSize: prompt.length,
            timestamp: Date.now(),
          };
        }
        return enforced;
      });
  }

  // ── Normalize evidence to array (AI may return single object) ────
  function _normalizeEvidence(result) {
    if (!result || !Array.isArray(result.themes)) return result;
    result.themes.forEach(function (theme) {
      if (!Array.isArray(theme.bullets)) return;
      theme.bullets.forEach(function (b) {
        if (!b) return;
        if (b.evidence == null) { b.evidence = []; return; }
        if (Array.isArray(b.evidence)) return;
        if (typeof b.evidence === "object") { b.evidence = [b.evidence]; return; }
        b.evidence = [];
      });
    });
    return result;
  }

  // ── Validate evidence quotes against KNOWN atomic-edit text ──────
  // The fundamental anti-hallucination check: the AI must only cite
  // text it was actually given. If it cites text from the surrounding
  // context (e.g., pre-existing contract language) and presents it as
  // a counterparty insertion, that's a hallucination — drop the bullet.
  //
  // Matching is fuzzy: normalize whitespace + casing, then check whether
  // the AI's quote is a substring of any known edit's text (or vice
  // versa, for short quotes the AI summarized). If neither, the quote
  // isn't anchored to a real change — drop it.
  function _validateEvidence(result, atomicEdits) {
    if (!result || !Array.isArray(result.themes)) return result;
    var norm = function (s) {
      return String(s || "").toLowerCase()
        .replace(/[‘’]/g, "'")
        .replace(/[“”]/g, '"')
        .replace(/\s+/g, " ")
        .trim();
    };
    // Pool of every known edit's text — what the AI was allowed to cite.
    var knownTexts = (atomicEdits || []).map(function (c) {
      return norm(c.text);
    }).filter(function (t) { return t.length > 0; });

    // Length thresholds tuned for the failure mode we saw in the wild:
    // a 6-char known edit "olgate" was being treated as anchoring a
    // 98-char hallucinated quote (because "olgate" appears inside the
    // word "Colgate"). The fix: long AI quotes can only be anchored by
    // SUBSTANTIAL (≥ MIN_ANCHOR chars) known edits.
    var MIN_ANCHOR = 30;
    var quoteMatchesKnown = function (quote) {
      var q = norm(quote);
      if (!q) return false;
      // Short AI quotes (< MIN_ANCHOR chars): the AI may have summarized
      // a real change into a brief quote. Accept if it's a substring of
      // any known edit text — but it must be a substring of the EDIT,
      // not the other way around. (A 5-char known edit "fifty" isn't
      // allowed to anchor a 4-char quote "iftn".)
      if (q.length < MIN_ANCHOR) {
        return knownTexts.some(function (t) { return t.indexOf(q) !== -1; });
      }
      // Long AI quotes (≥ MIN_ANCHOR chars): we need a substantial
      // anchor. Match either direction, but the matching known edit
      // MUST itself be ≥ MIN_ANCHOR chars long. This prevents a
      // 6-char fragment from "validating" a 98-char hallucinated
      // sentence just because the fragment appears as a substring of
      // some common word inside it.
      return knownTexts.some(function (t) {
        if (t.length < MIN_ANCHOR) return false;
        if (t.indexOf(q) !== -1) return true;
        if (q.indexOf(t) !== -1) return true;
        return false;
      });
    };

    var dropped = [];
    result.themes.forEach(function (theme) {
      if (!Array.isArray(theme.bullets)) return;
      theme.bullets = theme.bullets.filter(function (b) {
        var ev = Array.isArray(b.evidence) ? b.evidence : [];
        if (!ev.length) {
          dropped.push({
            theme: theme.title || "",
            text: b.text || "",
            reason: "No evidence entries — bullet dropped per anti-hallucination policy.",
          });
          return false;
        }
        // EVERY evidence quote must match a known atomic edit.
        var unmatchedQuotes = ev.filter(function (e) {
          return !quoteMatchesKnown(e && e.quote);
        });
        if (unmatchedQuotes.length === ev.length) {
          // ALL quotes are unanchored — definite hallucination
          dropped.push({
            theme: theme.title || "",
            text: b.text || "",
            quote: ev.map(function (e) { return (e && e.quote) || ""; }).filter(Boolean).join(" | "),
            reason: "Evidence quote(s) not found in any tracked change text — likely context hallucination.",
          });
          return false;
        }
        if (unmatchedQuotes.length > 0) {
          // SOME quotes unanchored — drop just those, keep the bullet
          // if at least one quote is valid.
          var validEv = ev.filter(function (e) {
            return quoteMatchesKnown(e && e.quote);
          });
          b.evidence = validEv;
          dropped.push({
            theme: theme.title || "",
            text: b.text || "",
            quote: unmatchedQuotes.map(function (e) { return (e && e.quote) || ""; }).join(" | "),
            reason: "Partial: " + unmatchedQuotes.length + " of " + ev.length + " evidence entries unmatched — those dropped, bullet kept.",
          });
        }
        return true;
      });
    });
    result._droppedBullets = dropped;
    return result;
  }

  // ── Post-AI 1:1 enforcement ──────────────────────────────────────
  // Even with the strictest prompt, models sometimes merge sibling
  // edits into one bullet with 4 evidence entries. We mechanically
  // split those into N bullets — one evidence per bullet — so the
  // user never sees a bullet that mixes contradictory siblings.
  //
  // Heuristic for "true substitution" (one allowed multi-evidence
  // pattern): exactly 2 entries, one DELETED + one INSERTED. Anything
  // else with > 1 evidence entries gets split.
  function _enforceOneToOne(result) {
    if (!result || !Array.isArray(result.themes)) return result;
    result.themes.forEach(function (theme) {
      if (!Array.isArray(theme.bullets)) return;
      var splitBullets = [];
      theme.bullets.forEach(function (b) {
        var ev = Array.isArray(b.evidence) ? b.evidence : [];
        // True substitution: exactly 2 entries, one delete + one insert.
        // Keep as one bullet.
        if (ev.length === 2) {
          var acts = ev.map(function (e) { return String((e && e.action) || "").toLowerCase(); });
          var isSub = (acts.indexOf("deleted") !== -1 && acts.indexOf("inserted") !== -1)
                    || (acts.indexOf("replaced") !== -1);
          if (isSub) { splitBullets.push(b); return; }
        }
        if (ev.length <= 1) { splitBullets.push(b); return; }
        // Multi-evidence + not a substitution → SPLIT.
        // Strategy: parse the bullet text for sentence-like clauses and
        // pair them with evidence entries by order; fall back to using
        // the bullet's first clause + an "and also" tag for later ones.
        ev.forEach(function (e, i) {
          var copy = Object.assign({}, b);
          copy.evidence = [e];
          // Tag split bullets with a marker so the reader knows this
          // came from JS-side fan-out, not from the model directly.
          var actLabel = String((e && e.action) || "").toLowerCase();
          var hint = actLabel === "inserted" ? "Inserted clause"
                   : actLabel === "deleted"  ? "Deleted clause"
                   : actLabel === "moved"    ? "Moved clause"
                   : "Clause";
          // Try to derive bullet text from the quote itself: first sentence
          // of the quote, or the whole quote if short.
          var q = String((e && e.quote) || "").trim();
          var firstSent = q.split(/(?<=[.!?])\s+/)[0] || q;
          // If the original text was a synthesis ("Introduced X, Y, Z, but
          // then…"), we replace it with a per-clause description. Prepend
          // ⚠ if the original bullet had it (likely a tension flag).
          var keepWarn = /^[⚠⚠️]\s*/.test(b.text || "") ? "⚠ " : "";
          copy.text = keepWarn + hint + ": " + firstSent;
          // Tag for UI awareness (used later if we want to surface splits)
          copy._splitFromMulti = true;
          copy._splitIndex = i + 1;
          copy._splitTotal = ev.length;
          splitBullets.push(copy);
        });
      });
      theme.bullets = splitBullets;
    });
    return result;
  }

  // ── Rendering ─────────────────────────────────────────────────────
  function _esc(s) {
    return String(s == null ? "" : s)
      .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;").replace(/'/g, "&#39;");
  }
  function _goBack() {
    try { eli.fsm.transition("idle"); } catch (_e) {}
    if (eli.dashboard && eli.dashboard.goHome) eli.dashboard.goHome();
  }

  function _renderHeader(mount, changeCount) {
    return '<div class="_rn_header">' +
      '<button class="_rn_back" type="button" title="Back">←</button>' +
      '<div class="_rn_header_main">' +
        '<div class="_rn_header_eyebrow">BETA · ADMIN</div>' +
        '<div class="_rn_header_title">📰 Redline Narrator</div>' +
      '</div>' +
      (changeCount != null
        ? '<div class="_rn_header_count">' + changeCount + ' change' + (changeCount === 1 ? "" : "s") + '</div>'
        : '') +
    '</div>';
  }

  function _renderLoading(mount, msg) {
    mount.innerHTML =
      '<div class="_rn_root">' +
        _renderHeader(mount, null) +
        '<div class="_rn_loading">' +
          '<div class="_rn_spinner"></div>' +
          '<div class="_rn_loading_text">' + _esc(msg) + '</div>' +
        '</div>' +
      '</div>';
    var b = mount.querySelector("._rn_back");
    if (b) b.onclick = _goBack;
  }

  function _renderEmpty(mount) {
    mount.innerHTML =
      '<div class="_rn_root">' +
        _renderHeader(mount, 0) +
        '<div class="_rn_empty">' +
          '<div class="_rn_empty_icon">📭</div>' +
          '<div class="_rn_empty_title">No tracked changes</div>' +
          '<div class="_rn_empty_desc">Open a redlined draft and run Redline Narrator again to get a plain-English summary.</div>' +
        '</div>' +
      '</div>';
    mount.querySelector("._rn_back").onclick = _goBack;
  }

  function _renderError(mount, err) {
    var msg = (err && err.message) || "Unknown error";
    mount.innerHTML =
      '<div class="_rn_root">' +
        _renderHeader(mount, null) +
        '<div class="_rn_empty">' +
          '<div class="_rn_empty_icon">⚠️</div>' +
          '<div class="_rn_empty_title">Couldn\'t generate summary</div>' +
          '<div class="_rn_empty_desc">' + _esc(msg) + '</div>' +
          '<button class="_rn_btn _rn_btn_retry" type="button" style="margin-top:14px;">Try again</button>' +
        '</div>' +
      '</div>';
    mount.querySelector("._rn_back").onclick = _goBack;
    mount.querySelector("._rn_btn_retry").onclick = function () { _show(); };
  }

  // Authors found in the doc, with You/Counterparty labels. Transparency
  // about what the AI is and isn't summarizing.
  function _renderAuthorsPanel(meta) {
    if (!meta || !meta.authors || !meta.authors.length) return "";
    var chips = meta.authors.map(function (a) {
      var role = a.isSelf ? "you" : "counterparty";
      return '<span class="_rn_author _rn_author_' + role + '">' +
        '<span class="_rn_author_name">' + _esc(a.name) + '</span>' +
        '<span class="_rn_author_role">' + (a.isSelf ? "you · ignored" : "counterparty") + '</span>' +
        '<span class="_rn_author_count">' + a.count + '</span>' +
      '</span>';
    }).join("");
    var note = !meta.selfName
      ? '<div class="_rn_authors_warn">⚠ Couldn\'t detect your name from Office identity — all authors are treated as counterparty. Set your name in Settings to filter accurately.</div>'
      : '';
    return '<div class="_rn_authors_panel">' +
      '<div class="_rn_authors_label">Authors detected</div>' +
      '<div class="_rn_authors_chips">' + chips + '</div>' +
      note +
    '</div>';
  }

  // ── Debug panel — show actual AI input + raw output side-by-side ──
  // Solves "why does the AI keep doing X?" with receipts. Shows:
  //   1. Atomic-split changes the AI received (per-Edit text, parent
  //      Word edit grouping, sections, type)
  //   2. Raw AI JSON output (bullets the model returned, BEFORE the
  //      JS-side 1:1 enforcer touched anything)
  //   3. Diff vs final result (which bullets the enforcer split)
  //   4. Run metadata (prompt size, timestamp)
  // Lets us see if the AI is merging (its fault) or if the post-
  // processor isn't kicking in (our fault).
  function _renderDebugHtml(result) {
    var d = (result && result._debug) || {};
    var input = Array.isArray(d.inputChanges) ? d.inputChanges : [];
    var raw = d.rawAiOutput || {};
    var rawThemes = Array.isArray(raw.themes) ? raw.themes : [];
    var finalThemes = Array.isArray(result.themes) ? result.themes : [];

    // Count bullets in raw vs final — if final > raw, the JS splitter fired
    var rawBulletCount = rawThemes.reduce(function (n, t) {
      return n + ((t.bullets && t.bullets.length) || 0);
    }, 0);
    var finalBulletCount = finalThemes.reduce(function (n, t) {
      return n + ((t.bullets && t.bullets.length) || 0);
    }, 0);
    var splitsFired = finalBulletCount - rawBulletCount;

    var html =
      '<div class="_rn_debug">' +
        '<div class="_rn_debug_head">' +
          '<span class="_rn_debug_title">🔍 DIAGNOSTIC</span>' +
          '<button class="_rn_debug_copy_raw _rn_btn" type="button">Copy debug JSON</button>' +
        '</div>' +
        '<div class="_rn_debug_stats">' +
          '<div><b>Atomic edits sent to AI:</b> ' + input.length + '</div>' +
          '<div><b>Bullets AI returned (raw):</b> ' + rawBulletCount + '</div>' +
          '<div><b>Bullets after JS 1:1 enforcement:</b> ' + finalBulletCount +
            (splitsFired > 0 ? ' (<span style="color:#c9a227">post-processor split +' + splitsFired + '</span>)'
                             : ' (no splits)') + '</div>' +
          '<div><b>Prompt size:</b> ' + (d.promptSize || 0).toLocaleString() + ' chars</div>' +
          '<div><b>Timestamp:</b> ' + (d.timestamp ? new Date(d.timestamp).toLocaleString() : "—") + '</div>' +
        '</div>';

    // ─ Section 1: Atomic input ─
    html += '<details class="_rn_debug_section" open><summary><b>1. Atomic-split changes sent to AI (' + input.length + ')</b></summary>';
    if (!input.length) {
      html += '<div class="_rn_debug_empty">No input changes.</div>';
    } else {
      input.forEach(function (c, i) {
        var partTag = (c.partCount > 1)
          ? '<span class="_rn_debug_part">part ' + c.partIdx + '/' + c.partCount + ' of Word edit #' + c.parentChangeIdx + '</span>'
          : '';
        var typeTag = '<span class="_rn_debug_type _rn_debug_type_' + (c.type || "x") + '">' + (c.type || "?") + '</span>';
        html += '<div class="_rn_debug_change">' +
          '<div class="_rn_debug_change_head">' +
            '<b>Edit #' + (i + 1) + '</b>  ' + typeTag + '  ' + partTag +
            '  <span class="_rn_debug_author">by ' + _esc(c.author || "?") + '</span>' +
          '</div>' +
          '<div class="_rn_debug_text">' + _esc(c.text || "") + '</div>' +
          (c.sectionHints && c.sectionHints.length
            ? '<div class="_rn_debug_hints">Section hints: [' + c.sectionHints.map(_esc).join(", ") + ']</div>'
            : '') +
        '</div>';
      });
    }
    html += '</details>';

    // ─ Section 2: Raw AI output ─
    html += '<details class="_rn_debug_section" open><summary><b>2. Raw AI output (bullets BEFORE JS 1:1 splitter)</b></summary>';
    if (!rawThemes.length) {
      html += '<div class="_rn_debug_empty">AI returned no themes.</div>';
    } else {
      rawThemes.forEach(function (t) {
        var bullets = Array.isArray(t.bullets) ? t.bullets : [];
        html += '<div class="_rn_debug_theme"><b>' + _esc((t.icon || "•") + " " + (t.title || "")) + '</b> (' + bullets.length + ' bullet' + (bullets.length === 1 ? '' : 's') + ')';
        bullets.forEach(function (b, bi) {
          var ev = Array.isArray(b.evidence) ? b.evidence : [];
          // Multi-evidence flag — what the splitter looks at
          var multiTag = ev.length > 1
            ? ' <span style="background:#fef9e7;color:#7c4a03;border:1px solid #e6c84a;padding:1px 5px;border-radius:3px;font-size:9px;font-weight:900;">MULTI: ' + ev.length + ' evidence</span>'
            : '';
          html += '<div class="_rn_debug_bullet">' +
            '<div><b>Bullet ' + (bi + 1) + ':</b> ' + _esc(b.text || "") + multiTag + '</div>';
          if (ev.length) {
            html += '<ul class="_rn_debug_evidence">';
            ev.forEach(function (e) {
              html += '<li><b>' + _esc((e.action || "").toUpperCase()) + ':</b> "' + _esc(e.quote || "") + '"' +
                (e.replacement ? ' → "' + _esc(e.replacement) + '"' : '') + '</li>';
            });
            html += '</ul>';
          }
          html += '</div>';
        });
        html += '</div>';
      });
    }
    html += '</details>';

    // ─ Section 3: What changed (post-AI processing) ─
    html += '<details class="_rn_debug_section"><summary><b>3. What the JS post-processor did</b></summary>';
    if (splitsFired > 0) {
      html += '<div class="_rn_debug_split_yes">⚠ Splitter fired: model returned ' + rawBulletCount + ' bullets, JS expanded to ' + finalBulletCount + '. Bullets with > 1 evidence (and not paired delete+insert) were torn apart.</div>';
    } else if (rawBulletCount > finalBulletCount) {
      html += '<div class="_rn_debug_split_yes">⚠ Final has FEWER bullets than raw — likely the validator dropped hallucinated bullets (see section 4).</div>';
    } else {
      html += '<div class="_rn_debug_split_no">✓ No splits needed. AI returned 1 evidence per bullet (or true delete+insert substitutions).</div>';
    }
    html += '</details>';

    // ─ Section 4: Hallucinated / dropped bullets ─
    var dropped = Array.isArray(d.droppedBullets) ? d.droppedBullets : [];
    html += '<details class="_rn_debug_section"' + (dropped.length ? ' open' : '') + '><summary><b>4. Bullets dropped by anti-hallucination validator (' + dropped.length + ')</b></summary>';
    if (!dropped.length) {
      html += '<div class="_rn_debug_split_no">✓ No bullets dropped — every bullet\'s evidence was anchored to a real tracked change.</div>';
    } else {
      html += '<div class="_rn_debug_split_yes">⚠ ' + dropped.length + ' bullet(s) the AI generated had evidence quotes that don\'t appear in any actual tracked change — likely citing the surrounding context as if it were a counterparty edit. These were dropped:</div>';
      dropped.forEach(function (b, i) {
        html += '<div class="_rn_debug_bullet" style="margin-top:8px;border-left:3px solid #ef4444;background:#fef2f2">' +
          '<div><b>Dropped ' + (i + 1) + ' (theme: ' + _esc(b.theme || "?") + '):</b> ' + _esc(b.text || "") + '</div>' +
          (b.quote ? '<div style="margin-top:4px;font-style:italic;color:#7f1d1d">Phantom quote: "' + _esc(b.quote) + '"</div>' : '') +
          '<div style="margin-top:4px;font-size:10.5px;color:#991b1b"><b>Reason:</b> ' + _esc(b.reason || "") + '</div>' +
        '</div>';
      });
    }
    html += '</details>';

    html += '</div>';
    return html;
  }

  function _renderResult(mount, result, fromCache, meta) {
    var changeCount = meta && meta.totalChanges || 0;
    var cpCount = meta && meta.cpChanges || 0;
    var html =
      '<div class="_rn_root">' +
        _renderHeader(mount, changeCount) +
        '<div class="_rn_body">' +
          _renderAuthorsPanel(meta) +
          '<div class="_rn_summary_card">' +
            '<div class="_rn_summary_eyebrow">✦ Counterparty Changes — Plain English' +
              (cpCount ? '  ·  ' + cpCount + ' edit' + (cpCount === 1 ? '' : 's') : '') +
            '</div>' +
            '<div class="_rn_summary_headline">' + _esc(result.headline || "(no headline)") + '</div>' +
          '</div>';

    var themes = Array.isArray(result.themes) ? result.themes : [];
    if (!themes.length) {
      html += '<div class="_rn_only_stylistic">No substantive edits detected. All tracked changes appear to be stylistic or formatting-only.</div>';
    } else {
      themes.forEach(function (theme) {
        var icon = String((theme && theme.icon) || "•").trim() || "•";
        var title = String((theme && theme.title) || "").trim();
        var bullets = Array.isArray(theme.bullets) ? theme.bullets : [];
        html += '<div class="_rn_theme">' +
          '<div class="_rn_theme_head">' +
            '<span class="_rn_theme_icon">' + _esc(icon) + '</span>' +
            '<span class="_rn_theme_title">' + _esc(title) + '</span>' +
          '</div>' +
          '<ul class="_rn_theme_list">';
        bullets.forEach(function (b) {
          // Bullet shape (schema v3): {text, sections[], evidence[]}.
          // Tolerate legacy shapes — string (v1) or no-evidence (v2).
          var text = (typeof b === "string") ? b : String((b && b.text) || "");
          var sections = (b && Array.isArray(b.sections)) ? b.sections : [];
          var evidence = (b && Array.isArray(b.evidence)) ? b.evidence : [];

          // Locate pills (gold)
          var pills = sections.filter(function (s) { return s && String(s).trim(); }).map(function (s) {
            var ref = String(s).trim();
            return '<button class="_rn_locate" type="button" data-sec="' + _esc(ref) + '" ' +
              'title="Jump to ' + _esc(ref) + ' in the document">' +
              '<span class="_rn_locate_icon">📍</span>' +
              '<span class="_rn_locate_ref">' + _esc(ref) + '</span>' +
            '</button>';
          }).join("");

          // Evidence block — the receipts. Each entry is "action + quote"
          // (and replacement for substitutions). Quotes are verbatim from
          // the counterparty's tracked changes, so the user can scan the
          // doc for them to verify the bullet's claim.
          var evidenceHtml = "";
          if (evidence.length) {
            var items = evidence.map(function (e) {
              if (!e || !e.quote) return "";
              var action = String(e.action || "").trim().toLowerCase();
              var quote = String(e.quote).trim();
              var replacement = String(e.replacement || "").trim();
              var actionClass = "_rn_evi_" + (
                action === "inserted" ? "ins" :
                action === "deleted" ? "del" :
                action === "replaced" ? "rep" :
                action === "moved" ? "mov" : "other"
              );
              var actionLabel = action ? action.toUpperCase() : "QUOTED";
              var body =
                '<span class="_rn_evi_quote">"' + _esc(quote) + '"</span>';
              if (replacement) {
                body +=
                  '<span class="_rn_evi_arrow">→</span>' +
                  '<span class="_rn_evi_quote _rn_evi_quote_new">"' + _esc(replacement) + '"</span>';
              }
              return '<div class="_rn_evi_item">' +
                '<span class="_rn_evi_action ' + actionClass + '">' + _esc(actionLabel) + '</span>' +
                body +
              '</div>';
            }).filter(Boolean).join("");
            if (items) {
              evidenceHtml = '<div class="_rn_evidence">' +
                '<div class="_rn_evi_label">Evidence</div>' +
                items +
              '</div>';
            }
          }

          html += '<li>' +
            '<span class="_rn_bullet_text">' + _esc(text) + '</span>' +
            (pills ? '<span class="_rn_bullet_locates">' + pills + '</span>' : '') +
            evidenceHtml +
          '</li>';
        });
        html += '</ul></div>';
      });
    }

    html +=
        '<div class="_rn_actions">' +
          '<button class="_rn_btn _rn_btn_copy" type="button">📋 Copy summary</button>' +
          '<button class="_rn_btn _rn_btn_regen" type="button">🔄 Regenerate</button>' +
          (result && result._debug
            ? '<button class="_rn_btn _rn_btn_debug" type="button">🔍 Debug</button>'
            : '') +
        '</div>' +
        (fromCache
          ? '<div class="_rn_cache_note">↩ Loaded from cache — click Regenerate for a fresh take.</div>'
          : '') +
        '<div class="_rn_debug_panel" style="display:none"></div>' +
      '</div></div>';

    mount.innerHTML = html;
    mount.querySelector("._rn_back").onclick = _goBack;
    mount.querySelector("._rn_btn_copy").onclick = function () {
      var txt = _resultToText(result, changeCount);
      try {
        navigator.clipboard.writeText(txt).then(function () {
          if (typeof showToast === "function") showToast("Copied to clipboard", "ok");
        }).catch(function () {
          if (typeof showToast === "function") showToast("Copy failed", "err");
        });
      } catch (_e) {
        if (typeof showToast === "function") showToast("Copy not available", "warn");
      }
    };
    mount.querySelector("._rn_btn_regen").onclick = function () {
      // Force a fresh AI call by clearing the cache for this doc and re-running.
      _show({ forceRegen: true });
    };
    var debugBtn = mount.querySelector("._rn_btn_debug");
    var debugPanel = mount.querySelector("._rn_debug_panel");
    if (debugBtn && debugPanel) {
      debugBtn.onclick = function () {
        if (debugPanel.style.display === "none") {
          debugPanel.innerHTML = _renderDebugHtml(result);
          debugPanel.style.display = "block";
          debugBtn.textContent = "🔍 Hide debug";
          var copyJsonBtn = debugPanel.querySelector("._rn_debug_copy_raw");
          if (copyJsonBtn) {
            copyJsonBtn.onclick = function () {
              var json = JSON.stringify(result._debug, null, 2);
              try {
                navigator.clipboard.writeText(json);
                if (typeof showToast === "function") showToast("Debug JSON copied", "ok");
              } catch (_e) {}
            };
          }
        } else {
          debugPanel.style.display = "none";
          debugBtn.textContent = "🔍 Debug";
        }
      };
    }
    // Wire the locate pills. Click → jump to that section in Word.
    var pills = mount.querySelectorAll("._rn_locate");
    Array.prototype.forEach.call(pills, function (p) {
      p.onclick = function () {
        var ref = p.getAttribute("data-sec");
        if (!ref) return;
        p.classList.add("_rn_locate_busy");
        _locate(ref).then(function (ok) {
          p.classList.remove("_rn_locate_busy");
          if (!ok) {
            p.classList.add("_rn_locate_miss");
            if (typeof showToast === "function") showToast("Couldn't find " + ref + " in the document", "warn");
          } else {
            p.classList.add("_rn_locate_hit");
            setTimeout(function () { p.classList.remove("_rn_locate_hit"); }, 800);
          }
        }).catch(function (err) {
          p.classList.remove("_rn_locate_busy");
          if (typeof showToast === "function") showToast("Locate failed: " + (err && err.message || "unknown"), "err");
        });
      };
    });
  }

  // ── Locate a section reference in the Word doc ────────────────────
  // Tries several common phrasings ("Section 7.1", "Sec. 7.1", "§ 7.1",
  // bare "7.1"). First hit wins — selects it and Word's auto-scroll
  // brings it into view. Returns Promise<boolean> indicating whether a
  // hit was found.
  function _locate(sectionRef) {
    // Normalize: strip any "Section "/"Sec."/"§" prefix the AI might have
    // included so we control the search variations ourselves.
    var bare = String(sectionRef || "").trim()
      .replace(/^\s*(section|sec\.?|§|article|art\.?)\s+/i, "")
      .trim();
    if (!bare) return Promise.resolve(false);
    var patterns = [
      "Section " + bare,
      "Sec. " + bare,
      "§ " + bare,
      "Article " + bare,
      bare,                 // bare number as last resort
    ];
    return eli.host.runRaw("redline_narrator:locate", function (ctx) {
      var body = ctx.document.body;
      var results = patterns.map(function (p) {
        var r = body.search(p, { matchCase: false, matchWholeWord: false });
        r.load("items");
        return r;
      });
      return ctx.sync().then(function () {
        for (var i = 0; i < results.length; i++) {
          var items = results[i].items || [];
          if (items.length > 0) {
            items[0].select();
            return ctx.sync().then(function () { return true; });
          }
        }
        return false;
      });
    });
  }

  function _resultToText(result, count) {
    var lines = [];
    lines.push("Redline Narrator — " + count + " tracked change" + (count === 1 ? "" : "s"));
    lines.push("");
    lines.push(result.headline || "");
    lines.push("");
    (result.themes || []).forEach(function (t) {
      lines.push((t.icon || "•") + " " + (t.title || ""));
      (t.bullets || []).forEach(function (b) {
        var text = (typeof b === "string") ? b : String((b && b.text) || "");
        var sections = (b && Array.isArray(b.sections)) ? b.sections : [];
        var evidence = (b && Array.isArray(b.evidence)) ? b.evidence : [];
        var refs = sections.filter(Boolean).map(function (s) { return "§ " + s; }).join(", ");
        lines.push("  • " + text + (refs ? "  (" + refs + ")" : ""));
        evidence.forEach(function (e) {
          if (!e || !e.quote) return;
          var act = String(e.action || "").trim().toLowerCase();
          var quote = '"' + String(e.quote).trim() + '"';
          var arrow = e.replacement ? ' → "' + String(e.replacement).trim() + '"' : "";
          lines.push("      ↳ " + (act ? act + ": " : "") + quote + arrow);
        });
      });
      lines.push("");
    });
    return lines.join("\n").trim();
  }

  // ── Main entry ────────────────────────────────────────────────────
  function _show(opts) {
    opts = opts || {};
    var mount = document.getElementById("_eli3_dashboard_root");
    if (!mount) return;
    try { eli.fsm.transition("rendering"); } catch (_e) {}
    _renderLoading(mount, "Reading tracked changes…");

    _readChanges().then(function (doc) {
      if (!doc || !doc.changes || !doc.changes.length) {
        _renderEmpty(mount);
        return;
      }
      var selfName = _currentUserName();
      // Counterparty change count for the UI badge — only what AI will narrate.
      var cpChanges = selfName
        ? doc.changes.filter(function (c) { return c.author.toLowerCase() !== selfName.toLowerCase(); })
        : doc.changes;
      var authorList = (function () {
        var counts = {};
        doc.changes.forEach(function (c) { counts[c.author] = (counts[c.author] || 0) + 1; });
        return Object.keys(counts).map(function (a) {
          return { name: a, count: counts[a], isSelf: selfName && a.toLowerCase() === selfName.toLowerCase() };
        }).sort(function (a, b) { return b.count - a.count; });
      })();
      var hintCount = doc.changes.reduce(function (acc, c) {
        return acc + (c.sectionHints && c.sectionHints.length ? 1 : 0);
      }, 0);
      var metaCtx = {
        selfName: selfName,
        authors: authorList,
        totalChanges: doc.changes.length,
        cpChanges: cpChanges.length,
        changesWithHints: hintCount,
      };

      var fp = doc.changes.map(function (c) { return c.type + "|" + c.author + "|" + c.text; }).join("##");
      // SCHEMA_VERSION in the hash input → bumping it (e.g. when the AI's
      // output shape changes) makes every prior cached result unreachable.
      var docHash = _hash("v" + SCHEMA_VERSION + "::" + (doc.bodyText || "").slice(0, 5000) + "::" + (selfName || "") + "::" + fp);
      var maybeCache = opts.forceRegen ? Promise.resolve(null) : _load(docHash);
      return maybeCache.then(function (cached) {
        if (cached) {
          _renderResult(mount, cached, true, metaCtx);
          return;
        }
        _renderLoading(mount, "Synthesizing counterparty changes…");
        return _generate(doc.changes, selfName).then(function (result) {
          _save(docHash, result);
          _renderResult(mount, result, false, metaCtx);
        });
      });
    }).catch(function (err) {
      _renderError(mount, err);
    });
  }

  eli.register({
    tile: { app_redline_narrator: _show },
  });

  eli.log.event("tool", "redline_narrator_initialized", {});
}

jsonTools.css:
/* Redline Narrator — premium light surface, gold accents, themed bullet
   cards. Same design language as Build Draft / Agreement at a Glance. */

/* Debug panel — receipts for why a bullet looks the way it does.
   Light dev surface, monospace, collapsible sections. Lives below the
   action row; only renders when result._debug is present. */
._rn_debug_panel {
  margin: 16px 8px 24px;
  border: 1px solid #cbd5e1;
  border-radius: 8px;
  background: #f8fafc;
  font-family: ui-monospace, "SF Mono", Consolas, "Courier New", monospace;
  font-size: 11.5px;
  line-height: 1.5;
  color: #1e293b;
}
._rn_debug {
  padding: 12px 14px;
}
._rn_debug_head {
  display: flex; justify-content: space-between; align-items: center;
  margin-bottom: 10px;
}
._rn_debug_title {
  font: 900 11px/1 'Inter', sans-serif;
  letter-spacing: 0.18em; text-transform: uppercase;
  color: #c9a227;
}
._rn_debug_stats {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 6px 18px;
  background: #fff;
  border: 1px solid #e2e8f0;
  border-radius: 6px;
  padding: 10px 12px;
  margin-bottom: 12px;
  font-size: 11px;
}
._rn_debug_section {
  margin-top: 12px;
  background: #fff;
  border: 1px solid #e2e8f0;
  border-radius: 6px;
  padding: 10px 12px;
}
._rn_debug_section > summary {
  cursor: pointer;
  font: 700 11.5px/1.4 'Inter', sans-serif;
  color: #1e293b;
  padding: 2px 0;
  user-select: none;
}
._rn_debug_section[open] > summary { margin-bottom: 10px; }
._rn_debug_change {
  border-left: 3px solid #cbd5e1;
  padding: 6px 10px;
  margin: 8px 0;
  background: #f8fafc;
  border-radius: 0 4px 4px 0;
}
._rn_debug_change_head {
  font-size: 10.5px;
  margin-bottom: 4px;
}
._rn_debug_type {
  display: inline-block;
  padding: 1px 6px;
  border-radius: 3px;
  font: 900 9px/1 'Inter', sans-serif;
  letter-spacing: 0.08em;
  border: 1px solid;
}
._rn_debug_type_insertion { background: #f0fdf4; border-color: #86efac; color: #166534; }
._rn_debug_type_deletion  { background: #fef2f2; border-color: #fca5a5; color: #991b1b; }
._rn_debug_type_moved     { background: #f0f9ff; border-color: #93c5fd; color: #1e40af; }
._rn_debug_type_x         { background: #f1f5f9; border-color: #cbd5e1; color: #475569; }
._rn_debug_part {
  background: #fef9e7;
  border: 1px solid #e6c84a;
  color: #7c4a03;
  padding: 1px 6px;
  border-radius: 3px;
  font-size: 9.5px;
  font-weight: 700;
}
._rn_debug_author {
  font-size: 10px;
  color: #64748b;
}
._rn_debug_text {
  font-family: ui-monospace, monospace;
  font-size: 11px;
  white-space: pre-wrap;
  word-break: break-word;
  background: #fff;
  border: 1px solid #e2e8f0;
  padding: 6px 8px;
  border-radius: 4px;
  margin: 4px 0;
}
._rn_debug_hints {
  font-size: 10px;
  color: #64748b;
  font-style: italic;
}
._rn_debug_theme {
  border-left: 3px solid #c9a227;
  padding: 6px 10px;
  margin: 8px 0;
  background: #fcfbf2;
  border-radius: 0 4px 4px 0;
}
._rn_debug_bullet {
  background: #fff;
  border: 1px solid #e2e8f0;
  padding: 6px 8px;
  border-radius: 4px;
  margin: 5px 0;
}
._rn_debug_evidence {
  margin: 4px 0 0 16px;
  padding: 0;
  font-size: 10.5px;
  color: #475569;
}
._rn_debug_evidence li { margin: 2px 0; }
._rn_debug_split_yes {
  background: #fef9e7;
  border: 1px solid #e6c84a;
  color: #7c4a03;
  padding: 8px 10px;
  border-radius: 4px;
  font-weight: 600;
}
._rn_debug_split_no {
  background: #f0fdf4;
  border: 1px solid #86efac;
  color: #166534;
  padding: 8px 10px;
  border-radius: 4px;
  font-weight: 600;
}
._rn_debug_empty {
  color: #94a3b8;
  font-style: italic;
  padding: 8px 0;
}
._rn_debug_copy_raw {
  font-size: 10.5px !important;
  padding: 4px 10px !important;
}


._rn_root {
  display: flex;
  flex-direction: column;
  width: 100%;
  height: 100%;
  box-sizing: border-box;
  background: #f8fafc;
  font-family: 'Inter', 'Segoe UI', system-ui, -apple-system, sans-serif;
  color: #0f172a;
}
/* Override the dark dashboard root background AND ensure the parent
   behaves as a full-bleed container — fixes the "spinner only on the
   left" symptom where the root was shrinking to content width. */
#_eli3_dashboard_root:has(._rn_root) {
  background: #f8fafc;
  display: block;
  width: 100%;
  height: 100%;
}

/* ── Header bar ─────────────────────────────────────────────────── */
._rn_header {
  flex: 0 0 auto;
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px 16px;
  background: linear-gradient(135deg, #0f172a 0%, #1e293b 100%);
  color: #f8fafc;
  border-bottom: 3px solid #c9a227;
  box-shadow: 0 2px 0 rgba(201,162,39,0.12), 0 4px 8px rgba(15,23,42,0.06);
}
._rn_back {
  flex: 0 0 auto;
  width: 30px; height: 30px;
  background: rgba(255,255,255,0.08);
  border: 1px solid rgba(255,255,255,0.18);
  color: #f8fafc;
  font-size: 16px;
  border-radius: 8px;
  cursor: pointer;
  transition: background .15s, transform .12s;
}
._rn_back:hover { background: rgba(255,255,255,0.16); }
._rn_back:active { transform: scale(0.95); }

._rn_header_main { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 1px; }
._rn_header_eyebrow {
  font-size: 9px; font-weight: 800; letter-spacing: 0.22em;
  text-transform: uppercase; color: #c9a227;
}
._rn_header_title { font-size: 16px; font-weight: 800; letter-spacing: 0.1px; }

._rn_header_count {
  flex: 0 0 auto;
  padding: 4px 10px;
  background: rgba(201,162,39,0.18);
  color: #fef3c7;
  border: 1px solid rgba(201,162,39,0.45);
  font-size: 11px; font-weight: 700; letter-spacing: 0.04em;
  border-radius: 0;
}

/* ── Body ───────────────────────────────────────────────────────── */
._rn_body {
  flex: 1; overflow-y: auto;
  padding: 20px 18px;
  display: flex; flex-direction: column; gap: 14px;
}

/* ── Authors panel — who's who in the doc ─────────────────────── */
._rn_authors_panel {
  padding: 12px 14px;
  background: #fff;
  border: 1px solid #e2e8f0;
  border-radius: 10px;
  box-shadow:
    inset 0 1px 0 rgba(255,255,255,0.85),
    0 1px 2px rgba(15,23,42,0.04);
}
._rn_authors_label {
  font: 800 9px/1 'Inter', sans-serif;
  letter-spacing: 0.22em; text-transform: uppercase;
  color: #94a3b8;
  margin-bottom: 8px;
}
._rn_authors_chips {
  display: flex; flex-wrap: wrap; gap: 6px;
}
._rn_author {
  display: inline-flex; align-items: center; gap: 6px;
  padding: 4px 6px 4px 9px;
  font: 700 11px/1 'Inter', sans-serif;
  border-radius: 6px;
  border: 1px solid;
}
._rn_author_you {
  background: #f1f5f9; border-color: #cbd5e1; color: #64748b;
  opacity: 0.85;
}
._rn_author_counterparty {
  background: #fef9e7; border-color: #e6c84a; color: #7c4a03;
}
._rn_author_name { font-weight: 800; }
._rn_author_role {
  font-size: 9px; font-weight: 700; letter-spacing: 0.08em;
  text-transform: uppercase; opacity: 0.75;
  padding-left: 4px; border-left: 1px solid currentColor; margin-left: 1px;
}
._rn_author_count {
  background: rgba(255,255,255,0.6);
  border: 1px solid currentColor;
  padding: 1px 6px;
  font-size: 10px; font-weight: 900;
  border-radius: 0;
}
._rn_authors_warn {
  margin-top: 8px;
  padding: 7px 10px;
  background: #fef9c3;
  border: 1px solid #eab308;
  border-radius: 6px;
  font: 600 11px/1.4 'Inter', sans-serif;
  color: #854d0e;
}

/* ── Hero summary card ──────────────────────────────────────────── */
._rn_summary_card {
  padding: 22px 24px;
  background: linear-gradient(180deg, #fffdf6 0%, #fef9e7 100%);
  border: 1px solid #c9a227;
  border-left: 4px solid #b8860b;
  border-radius: 12px;
  box-shadow:
    inset 0 1px 0 rgba(255,255,255,0.9),
    0 1px 2px rgba(184,134,11,0.06),
    0 8px 20px -4px rgba(184,134,11,0.18);
}
._rn_summary_eyebrow {
  font-size: 10px; font-weight: 900; letter-spacing: 0.24em;
  text-transform: uppercase; color: #7c2d12;
  margin-bottom: 8px;
}
._rn_summary_headline {
  font: 800 18px/1.4 'Georgia', 'Times New Roman', serif;
  color: #1a1407;
  letter-spacing: -0.1px;
}

/* ── Theme cards ────────────────────────────────────────────────── */
._rn_theme {
  background: #fff;
  border: 1px solid #e2e8f0;
  border-left: 3px solid #94a3b8;
  border-radius: 10px;
  padding: 14px 16px 12px;
  box-shadow:
    inset 0 1px 0 rgba(255,255,255,0.85),
    0 1px 2px rgba(15,23,42,0.04),
    0 4px 12px -4px rgba(15,23,42,0.06);
}
._rn_theme_head {
  display: flex; align-items: center; gap: 10px;
  margin-bottom: 8px;
  padding-bottom: 8px;
  border-bottom: 1px dashed #cbd5e1;
}
._rn_theme_icon {
  font-size: 18px; line-height: 1;
  filter: drop-shadow(0 1px 2px rgba(15,23,42,0.08));
}
._rn_theme_title {
  font-size: 11px; font-weight: 900; letter-spacing: 0.14em;
  text-transform: uppercase; color: #0f172a;
}
._rn_theme_list {
  list-style: none;
  margin: 0; padding: 0;
  display: flex; flex-direction: column; gap: 6px;
}
._rn_theme_list li {
  position: relative;
  padding-left: 18px;
  font-size: 12.5px; line-height: 1.55; color: #334155;
}
._rn_theme_list li::before {
  content: "▸";
  position: absolute;
  left: 4px; top: 0;
  color: #c9a227;
  font-size: 12px;
}
._rn_bullet_text { display: inline; }

/* Locate pills — premium gold-bordered chips after each bullet. Click
   jumps to that section in Word. Multiple pills wrap inline. */
._rn_bullet_locates {
  display: inline-flex;
  flex-wrap: wrap;
  gap: 4px;
  margin-left: 8px;
  vertical-align: middle;
}
._rn_locate {
  display: inline-flex; align-items: center; gap: 4px;
  padding: 3px 9px 3px 7px;
  background: linear-gradient(180deg, #ffffff 0%, #fefae3 100%);
  border: 1px solid #e6d28a;
  border-left: 2px solid #c9a227;
  border-radius: 999px;
  color: #7c4a03;
  font: 800 9.5px/1 'Inter', sans-serif;
  letter-spacing: 0.05em;
  cursor: pointer;
  box-shadow:
    inset 0 1px 0 rgba(255,255,255,0.9),
    0 1px 2px rgba(184,134,11,0.10);
  transition: all .15s cubic-bezier(0.2, 0.8, 0.2, 1);
  white-space: nowrap;
}
._rn_locate:hover {
  background: linear-gradient(180deg, #fffef9 0%, #fef9e7 100%);
  border-color: #d4b948;
  border-left-color: #b8901f;
  color: #5c3a02;
  box-shadow:
    inset 0 1px 0 rgba(255,255,255,0.95),
    0 2px 5px rgba(184,134,11,0.20);
  transform: translateY(-1px);
}
._rn_locate:active { transform: translateY(0); }
._rn_locate_icon { font-size: 10px; line-height: 1; opacity: 0.85; }
._rn_locate_ref { font-weight: 900; letter-spacing: 0; font-size: 10px; }
/* ── Evidence — verbatim citations under each bullet ───────────── */
/* The anti-hallucination strip. Each entry is a small action label
   (INSERTED / DELETED / REPLACED) + the actual quoted text from the
   counterparty's tracked change. Cream-tinted ground tying it to the
   page's gold accent palette; quiet so it doesn't compete with the
   primary bullet text. */
._rn_evidence {
  margin: 8px 0 0 0;
  padding: 8px 10px 8px 10px;
  background: #fcfbf2;
  border-left: 2px solid #c9a227;
  border-radius: 0 6px 6px 0;
  display: flex; flex-direction: column; gap: 5px;
}
._rn_evi_label {
  font: 900 8.5px/1 'Inter', sans-serif;
  letter-spacing: 0.22em; text-transform: uppercase;
  color: #94a3b8;
  margin-bottom: 3px;
}
._rn_evi_item {
  display: flex; align-items: baseline; gap: 7px;
  flex-wrap: wrap;
  font-size: 11.5px; line-height: 1.4;
}
._rn_evi_action {
  flex: 0 0 auto;
  display: inline-flex; align-items: center;
  padding: 1px 5px;
  font: 900 8.5px/1 'Inter', sans-serif;
  letter-spacing: 0.08em;
  border: 1px solid;
  border-radius: 3px;
}
._rn_evi_ins { background: #f0fdf4; border-color: #86efac; color: #166534; }
._rn_evi_del { background: #fef2f2; border-color: #fca5a5; color: #991b1b; }
._rn_evi_rep { background: #fef9e7; border-color: #e6c84a; color: #7c4a03; }
._rn_evi_mov { background: #f0f9ff; border-color: #93c5fd; color: #1e40af; }
._rn_evi_other { background: #f1f5f9; border-color: #cbd5e1; color: #475569; }
._rn_evi_quote {
  font-family: 'Georgia', 'Times New Roman', serif;
  color: #1e293b;
  font-style: italic;
  font-size: 12px;
}
._rn_evi_quote_new {
  color: #166534;
  font-weight: 600;
}
._rn_evi_arrow {
  color: #94a3b8;
  font-weight: 700;
  margin: 0 2px;
}

/* Hit animation — brief gold pulse after a successful locate. */
._rn_locate_hit {
  animation: _rn_locate_pulse 0.6s ease;
}
@keyframes _rn_locate_pulse {
  0%   { box-shadow: 0 0 0 0 rgba(201,162,39,0.7); }
  50%  { box-shadow: 0 0 0 8px rgba(201,162,39,0); }
  100% { box-shadow: inset 0 1px 0 rgba(255,255,255,0.9), 0 1px 2px rgba(184,134,11,0.10); }
}
/* Miss state — soft red border indicates the search came up empty. */
._rn_locate_miss {
  border-color: #fca5a5;
  border-left-color: #dc2626;
  color: #991b1b;
  background: linear-gradient(180deg, #fff 0%, #fee2e2 100%);
}
/* Busy state — disable interactions while the Word.run is in flight. */
._rn_locate_busy {
  opacity: 0.6;
  pointer-events: none;
}

._rn_only_stylistic {
  padding: 14px 16px;
  background: #f1f5f9;
  border: 1px solid #cbd5e1;
  border-left: 3px solid #94a3b8;
  font-size: 12px; color: #475569; font-style: italic;
  border-radius: 8px;
}

/* ── Action buttons ─────────────────────────────────────────────── */
._rn_actions {
  display: flex; gap: 10px; flex-wrap: wrap;
  margin-top: 8px;
}
._rn_btn {
  flex: 1 1 auto;
  padding: 10px 16px;
  background: linear-gradient(180deg, #ffffff 0%, #f1f5f9 100%);
  border: 1px solid #cbd5e1;
  color: #334155;
  font: 700 11.5px/1 'Inter', sans-serif;
  letter-spacing: 0.04em;
  cursor: pointer;
  border-radius: 8px;
  box-shadow:
    inset 0 1px 0 rgba(255,255,255,0.9),
    0 1px 2px rgba(15,23,42,0.05),
    0 4px 10px -4px rgba(15,23,42,0.08);
  transition: all .15s ease;
}
._rn_btn:hover {
  background: linear-gradient(180deg, #fffef9 0%, #fef9e7 100%);
  border-color: #d4b948;
  color: #7c4a03;
  box-shadow:
    inset 0 1px 0 rgba(255,255,255,0.95),
    0 1px 2px rgba(184,134,11,0.08),
    0 6px 14px -4px rgba(184,134,11,0.18);
  transform: translateY(-1px);
}
._rn_btn:active { transform: translateY(0); }
._rn_btn_copy { flex: 2 1 0; }   /* primary action a bit wider */

._rn_cache_note {
  margin-top: 6px;
  font-size: 10.5px; color: #94a3b8;
  text-align: center; font-style: italic;
}

/* ── Loading state ──────────────────────────────────────────────── */
._rn_loading {
  flex: 1;
  display: flex; flex-direction: column; align-items: center; justify-content: center;
  gap: 18px;
  padding: 60px 20px;
}
._rn_spinner {
  width: 40px; height: 40px;
  border: 3px solid #e2e8f0;
  border-top-color: #c9a227;
  border-radius: 50%;
  animation: _rn_spin 0.8s linear infinite;
}
@keyframes _rn_spin { to { transform: rotate(360deg); } }
._rn_loading_text {
  font-size: 13px; font-weight: 600; color: #475569;
}

/* ── Empty / error states ───────────────────────────────────────── */
._rn_empty {
  flex: 1;
  display: flex; flex-direction: column; align-items: center; justify-content: center;
  gap: 12px; padding: 60px 28px;
  text-align: center;
}
._rn_empty_icon { font-size: 48px; line-height: 1; opacity: 0.55; }
._rn_empty_title { font-size: 18px; font-weight: 800; color: #0f172a; letter-spacing: -0.2px; }
._rn_empty_desc { font-size: 12.5px; line-height: 1.5; color: #64748b; max-width: 360px; }
